  H.addText(c, 'TC OUT', 'OUT', x0 + w - 4 * u, by + 9 * u + fs * 0.35, fs * 0.6, { role: 'mono', align: 'right', color: sc.sub }, function (env) { return { alpha: 0.8 * baseA * E.outExpo(cl(env.lt / 0.5)) * outE(env) }; });
