      if (t < X1 - X0) { x = X0 + t; y = Y0; }
      else if ((t -= X1 - X0) < Y1 - Y0) { x = X1; y = Y0 + t; }
      else if ((t -= Y1 - Y0) < X1 - X0) { x = X1 - t; y = Y1; }
