  var py = base + 3 * u, pw = 6 * u;
  H.poly(c, 'Heading ptr', [[cx, py], [cx - pw, py + pw * 1.3], [cx + pw, py + pw * 1.3]], true, { fill: acc(c), alpha: 1 });
  var r0 = H.p(P, 'r', 0.25) * 360;
