  var right = P.right ? (W - bb.x1 - gap > 70 * u) : (bb.x0 - gap < 70 * u), sEnd = right ? W - bb.x1 - gap : bb.x0 - gap;
  if (sEnd < 40 * u) sEnd = Math.max(W - bb.x1 - gap, bb.x0 - gap);
  var n = 4 + ((H.p(P, 'n', 1) | 0) % 3), traces = [], pads = [];
