  var X = cl(sx < 0 ? bb.x0 - padP : bb.x1 + padP, m * 0.5, W - m * 0.5), Y = cl(sy < 0 ? bb.y0 - padP : bb.y1 + padP, m * 0.5, Hh - m * 0.5);
