  H.addText(c, 'Window title', 'lyric_' + pad2(((c.cut.line != null ? c.cut.line : 0) | 0) + 1) + '.txt', (x0 + x1) / 2, by, FS(c) * 0.92, { role: 'mono', align: 'center', color: sc.fg });
