  var ln = (c.cut.line | 0) + 1, gut = noNo(c) ? 0 : fs * 2.1, sg = fs * 1.2;
  var w = gut + sg + Math.max(tw(neu, fs), tw(old, fs)) + fs * 0.8, h = lh * 2 + fs * 1.3;
