  var m = H.decMG(c) * 0.5, fs = FS(c) * 0.78, pd = 18 * u + Math.min(bb.w, bb.h) * 0.1, col = P.accent ? acc(c) : sc.fg, lw = Math.max(1, 1.4 * u);
