  var fs = FS(c) * 0.85, n = Math.min(3, 1 + cl(H.p(P, 'n', 1) | 0, 1, 3)), labs = SL_LABS[(H.p(P, 'v', 0) | 0) % 3], rh = fs * 2.1, tr = 150 * u, nn = noNo(c);
