    for (var y = y0 + 1; y <= y1; y++) o[y * nx + x1] = k++;
    if (y1 > y0) for (var x2 = x1 - 1; x2 >= x0; x2--) o[y1 * nx + x2] = k++;
    if (x1 > x0) for (var y2 = y1 - 1; y2 > y0; y2--) o[y2 * nx + x0] = k++;
    x0++; y0++; x1--; y1--;
