        var poly = v ? rectPoly(0, u0 * Lx - 0.5, W, u0 * Lx + SW + 0.5, W, Hh) : rectPoly(u0 * Lx - 0.5, 0, u0 * Lx + SW + 0.5, Hh, W, Hh);
        var polys = Object.create(null);
