    if (!spans.length) return;
    var lc = markCol(c.sc, nodeCol(c, ng)), vert = !!ng.node.vertical;
    var s = ng.node.size, lw = Math.max(1.5, s * k), g = s * 0.3, arm = s * 0.36, leg = s * 0.74;
    var L0 = spans[0], L1 = spans[spans.length - 1];
