          var cp = cutProgress(c, ng, f), q = E.outExpo(cl((cp.lt - 0.1 - li * 0.08) / 0.5)), ok = outK(c, f);
          var pos = uvPt(vert, mid + d * half * q, off);
          return { 'position.x': pos[0], 'position.y': -pos[1], alpha: q * ok > 0.01 ? cl(ok) : 0 };
